-- Add missing columns to compliance_controls
ALTER TABLE public.compliance_controls 
ADD COLUMN IF NOT EXISTS status text DEFAULT 'not_implemented' CHECK (status IN ('implemented', 'not_implemented', 'planned')),
ADD COLUMN IF NOT EXISTS owner text,
ADD COLUMN IF NOT EXISTS last_review date;

